275	              "Use /exa-research start <topic>, list, resume <id>, approve <cycle-id> <total-dollar-ceiling> [tool,tool...], approve-request <cycle-id> <request-hash> <assessed-dollars>, approve-liability <cycle-id> <operation-id> <assessed-dollars>, approve-replacement <cycle-id> <unknown-attempt-id> <new-request-hash> <assessed-original-dollars>, or archive [id].",
276	            );
277	        }
278	        ctx.ui.notify(text, "info");
279	      } catch (error) {
280	        ctx.ui.notify(error instanceof Error ? error.message : String(error), "error");
281	      }
282	    },
283	  });
284	
285	  return {
286	    registerTool(tool) {
287	      const paid = tool.name.startsWith("web_");
288	      pi.registerTool({
289	        ...tool,
290	        ...(paid || tool.name.startsWith("exa_research_")
291	          ? { promptGuidelines: [...(tool.promptGuidelines ?? []), ...CYCLE_GUIDELINES] }
292	          : {}),
293	        ...(tool.name === "web_research_exa"
294	          ? {
295	              description: `${tool.description} Pi cycles: active mode executes only the approved compiled request. Explicit researchMode=retry after confirmed failure/nondispatch or researchMode=replace for unknown originals requires cycleId, fresh exact funding and total exposure approval. Replacement additionally requires an unused operator approve-replacement for EVERY unknown original; assistant risk flags/amounts never grant consent. No automatic retry, replacement or gap closing; any success blocks new submissions and duplicate successes remain visible. researchMode=recover performs one existing-run GET with explicit cycleId and optional attemptId; request overrides are forbidden and recovery never creates, polls or cancels. Explicitly resume saved state with exa_research_status action=resume first. previousRunId means new paid continuation, never recovery. Resume and inspection grant no spending permission.`,
296	            }
297	          : {}),
298	        ...(tool.name === "exa_research_status"
299	          ? {
300	              parameters: statusParams,
301	              description:
302	                "Inspect active cycle or discover saved cycle summaries without activating them. action=resume with explicit cycleId acquires exclusive saved-cycle ownership; it never grants spending permission. Recover an existing Agent attempt with web_research_exa researchMode=recover, never previousRunId continuation.",
303	            }
304	          : {}),
305	        ...(tool.name === "exa_research_step"
306	          ? {
307	              parameters: stepParams,
308	              description:
309	                "Update the active durable plan. evidence selects/rejects captured candidate IDs; selection requires a label and optional explicit notes. Record external evidence in sources, then select its ID with executionPlan.selectedEvidence. Use evidence decisions or selectedEvidence in one update, not both. executionPlan fields replace their whole persisted field; omitted fields remain unchanged. Processing rows remain explicit input.data/exclusion. Set a goal and draft-07 taskSchema before preview. This does not approve or dispatch work.",
310	            }
311	          : {}),
312	        ...(tool.name === "exa_research_summary"
313	          ? {
314	              parameters: summaryParams,
315	              description:
316	                "Preview the versioned compiled research request with mode execution_plan or payload; brief/source_pack inspect curated planner facts. Compile errors name fields to fix. Artifacts do not authorize paid work.",
317	            }
318	          : {}),
319	        ...(tool.name === "exa_research_reset"
320	          ? {
321	              description:
322	                "Detach and archive the active durable research cycle; retain history, attempts, grants and liabilities. Does not cancel remote work.",
323	            }
324	          : {}),
325	        ...(paid
326	          ? {
327	              parameters: Type.Evaluate(
328	                Type.Intersect([
329	                  tool.name === "web_research_exa" ? Type.Omit(tool.parameters, ["query"]) : tool.parameters,
330	                  Type.Object({
331	                    researchMode: Type.Optional(
332	                      Type.Union([
333	                        Type.Literal("active"),
334	                        Type.Literal("standalone"),
335	                        ...(tool.name === "web_research_exa"
336	                          ? [Type.Literal("recover"), Type.Literal("retry"), Type.Literal("replace")]
337	                          : []),
338	                      ]),
339	                    ),
340	                    ...targetProperties,
341	                    ...(tool.name === "web_research_exa"
342	                      ? {
343	                          query: Type.Optional(Type.String({ minLength: 1 })),
344	                          artifactHash: Type.Optional(Type.String()),
345	                          attemptId: Type.Optional(Type.String()),
346	                        }
347	                      : {}),
348	                  }),
349	                ]),
350	              ),
351	            }
352	          : {}),
353	        async execute(id, params, signal, onUpdate, ctx) {
354	          try {
355	            // Capture JSON input before the first await; caller-owned arrays
356	            // must not change the request after permission hashing/assessment.
357	            const paidInput = paid ? structuredClone(params) : undefined;
358	            const statusInput = tool.name === "exa_research_status" ? structuredClone(params) : undefined;
359	            const cycles = await get(ctx);
360	            if (tool.name === "exa_research_status") {
361	              if (!Value.Check(statusParams, statusInput)) throw new Error("Invalid cycle status action.");
362	              if (statusInput.action === "resume") {
363	                if (!statusInput.cycleId) throw new Error("Explicit cycleId is required to resume a saved cycle.");
364	                return result(
365	                  view(await cycles.resume(statusInput.cycleId, { expectedRevision: statusInput.expectedRevision })),
366	                );
367	              }
368	              const active = await cycles.status(statusInput);
369	              if (active) return result(view(active));
370	              const found = await cycles.discover();
371	              return result({
372	                active: false,
373	                savedCycles: found.cycles.map((cycle) => ({
374	                  id: cycle.id,
375	                  revision: cycle.revision,
376	                  status: cycle.status,
377	                  archived: cycle.archived ?? false,
378	                })),
379	                unreadableCycleIds: found.unreadableCycleIds,
380	                nextSafeAction:
381	                  "Explicitly resume a saved cycle with action=resume and cycleId, or use /exa-research start. Discovery never activates a cycle or grants spending permission.",
382	              });
383	            }
384	            const explicitStandalone =
385	              paid &&
386	              typeof paidInput === "object" &&
387	              paidInput !== null &&
388	              Reflect.get(paidInput, "researchMode") === "standalone";
389	            const record = explicitStandalone ? undefined : await cycles.status();
390	            if (paid) {
391	              if (typeof paidInput !== "object" || paidInput === null) throw new Error("Invalid tool arguments.");
392	              const { researchMode, cycleId, expectedRevision, artifactHash, attemptId, ...standalone } =
393	                paidInput as Record<string, unknown>;
394	              if (
395	                researchMode !== undefined &&
396	                researchMode !== "active" &&
397	                researchMode !== "standalone" &&
398	                researchMode !== "recover" &&
399	                researchMode !== "retry" &&
400	                researchMode !== "replace"
401	              ) {
402	                throw new Error("Invalid researchMode.");
403	              }
404	              const reference = { cycleId, expectedRevision, artifactHash };
405	              if (!Value.Check(referenceParams, reference)) throw new Error("Invalid artifact reference.");
406	              const transition = researchMode === "retry" || researchMode === "replace" ? researchMode : undefined;
407	              if (
408	                transition &&
409	                (tool.name !== "web_research_exa" || !record || typeof cycleId !== "string" || !cycleId)
410	              )
411	                throw new Error("Explicit retry/replacement requires a resumed cycleId and web_research_exa.");
412	              if (researchMode === "recover") {
413	                if (tool.name !== "web_research_exa")
414	                  throw new Error("Recovery is only supported by web_research_exa.");
415	                if (!record || typeof cycleId !== "string" || !cycleId)
416	                  throw new Error("Explicitly resume the saved cycle, then recover with its cycleId.");
417	                if (attemptId !== undefined && typeof attemptId !== "string") throw new Error("Invalid attemptId.");
418	                if (Object.keys(standalone).length)
419	                  throw new Error(
420	                    "EXECUTION_CONFLICT: Recovery accepts references only, never query/effort/continuation overrides.",
421	                  );
422	                if (!inspectionFactory)
423	                  throw new Error("Existing-run inspection is not enabled; no SDK request was dispatched.");
424	                const prepared = await cycles.prepareAgentRecovery({ ...reference, attemptId });
425	                let unavailable = false;
426	                try {
427	                  const inspector = inspectionFactory(prepared.runId, prepared.observer);
428	                  if (!inspector) throw new Error("Existing-run inspection is not enabled.");
429	                  const response = await inspector.execute(
430	                    id,
431	                    prepared.attempt.artifact.request,
432	                    signal,
433	                    onUpdate,
434	                    ctx,
435	                  );
436	                  unavailable = Boolean(response.isError);
437	                } catch {
438	                  unavailable = true;
439	                }
440	                if (unavailable) await prepared.onUnavailable();
441	                const current = await cycles.inspect(cycleId);
442	                const execution = current.attempts.find(
443	                  (entry) => Value.Check(agentAttemptSchema, entry) && entry.id === prepared.attempt.id,
444	                );
445	                const invalid =
446	                  !Value.Check(agentAttemptSchema, execution) ||
447	                  execution.result?.processing === "failed" ||
448	                  execution.status === "failed";
449	                return result(
450	                  {
451	                    cycleId,
452	                    attemptId: prepared.attempt.id,
453	                    inspectionOnly: true,
454	                    execution,
455	                    accounting: view(current).accounting,
456	                    status: current.status,
457	                    nextSafeAction: unavailable
458	                      ? "INSPECTION_UNAVAILABLE: This inspection did not confirm a fresh remote outcome; previously confirmed terminal outcomes remain. Inspect the same saved run again; this inspection grants no retry or replacement permission."
459	                      : "Review recovered state; pending/unknown work requires another explicit inspection, never automatic replacement. Findings do not satisfy criteria automatically.",
460	                  },
461	                  undefined,
462	                  unavailable || invalid,
463	                );
464	              }
465	              if (attemptId !== undefined) throw new Error("attemptId is only valid in explicit recovery mode.");
466	              if (
467	                researchMode === "standalone" &&
468	                (cycleId !== undefined || expectedRevision !== undefined || artifactHash !== undefined)
469	              )
470	                throw new Error(
471	                  "Standalone requests must omit cycle references; use active research for cycle-attributed spending.",
472	                );
473	              if (!record && (cycleId !== undefined || expectedRevision !== undefined))
474	                throw new Error("No active research cycle.");
475	              if (researchMode === "active" && !record) throw new Error("No active research cycle.");
476	              if (record && researchMode !== "standalone") {
477	                if (tool.name === "web_research_exa") {
478	                  if (!agentFactory) {
479	                    await cycles.preview({ ...reference, executionFields: standalone });
480	                    throw new Error(
481	                      "Integrated paid research is not available in this slice; no request was dispatched.",
482	                    );
483	                  }
484	                  const prepared = await cycles.reserveAgent({ ...reference, executionFields: standalone }, transition);
485	                  const { attempt, artifact, assessment } = prepared;
486	                  const observer = cycles.agentLifecycleObserver(attempt.cycleId, attempt.id, attempt.requestHash);
487	                  const callObserver: AgentLifecycleObserver = {
488	                    beforeCreate: observer.beforeCreate,
489	                    raw: async (phase, reply) => {
490	                      const remoteId = reply.id;
491	                      const remoteStatus = reply.status;
492	                      await observer.raw(phase, reply);
493	                      try {
494	                        const completionSummary = view(await cycles.inspect(attempt.cycleId)).completionSummary;
495	                        onUpdate?.(
496	                          result(
497	                            {
498	                              cycleId: attempt.cycleId,
499	                              attemptId: attempt.id,
500	                              phase,
501	                              remoteId,
502	                              remoteStatus,
503	                              completionSummary,
504	                            },
505	                            `Exa Agent ${remoteId}: ${remoteStatus}. ${completionSummary.duplicateSuccess ? "Duplicate successes are retained with separate costs; no further submission is permitted. " : ""}Progress is not final billing or criterion verification.`,
506	                          ),
507	                        );
508	                      } catch {
509	                        /* Display failure never authorizes replacement research. */
510	                      }
511	                    },
512	                  };
513	                  let response: Awaited<ReturnType<typeof tool.execute>>;
514	                  try {
515	                    const agent = agentFactory(callObserver);
516	                    if (!agent) throw new Error("Agent research is not enabled; no SDK request was dispatched.");
517	                    response = await agent.execute(id, artifact.request, signal, onUpdate, ctx);
518	                  } finally {
519	                    await observer.finish();
520	                  }
521	                  const current = await cycles.inspect(attempt.cycleId);
522	                  const execution = current.attempts.find(
523	                    (entry) => Value.Check(agentAttemptSchema, entry) && entry.id === attempt.id,
524	                  );
525	                  const currentView = view(current);
526	                  const accounting = currentView.accounting;
527	                  const incompleteOrInvalid =
528	                    !Value.Check(agentAttemptSchema, execution) || execution.result?.processing !== "validated";
529	                  return result(
530	                    {
531	                      tool: "web_research_exa",
532	                      cycleId: attempt.cycleId,
533	                      attemptId: attempt.id,
534	                      artifactHash: artifact.hash,
535	                      requestHash: attempt.requestHash,
536	                      assessment,
537	                      execution,
538	                      accounting,
539	                      status: current.status,
540	                      completionSummary: currentView.completionSummary,
541	                      nextSafeAction: currentView.nextSafeAction,
542	                      ...(currentView.finalReport ? { finalReport: currentView.finalReport } : {}),
543	                    },
544	                    `Exa cycle ${attempt.cycleId}; Agent attempt ${attempt.id}; status ${current.status}.\n${JSON.stringify(execution, null, 2)}\nUsage classification: ${JSON.stringify(accounting)}\n${currentView.finalReport ? `Final report (recorded gaps and criteria, not automatic verification): ${JSON.stringify(currentView.finalReport)}\n` : ""}${currentView.nextSafeAction}\nNo automatic retry, replacement or gap closing. Estimates are not vendor caps; API-reported costs are not independently verified invoices.`,
545	                    response.isError || incompleteOrInvalid,
546	                  );
547	                }
548	                if (!retrievalFactory || !EXPLORATION_TOOLS.some((name) => name === tool.name))
549	                  throw new Error(
550	                    "Integrated paid research is not available in this slice; no request was dispatched.",
551	                  );
552	                if (cycleId === undefined)
553	                  throw new Error("APPROVAL_REQUIRED: Explicit cycleId is required to attribute exploratory spending.");
554	                if (artifactHash !== undefined)
555	                  throw new Error("Artifact hashes apply to synthesis previews, not exploration.");
556	                if (!Value.Check(tool.parameters, standalone)) throw new Error("Invalid exploratory tool arguments.");
557	                const { operation, assessment } = await cycles.reserveExploration(tool.name, standalone, reference);
558	                const { cycleId: savedCycle, id: operationId, requestHash } = operation;
559	                const capture = cycles.explorationEvidenceObserver(savedCycle, operationId, requestHash);
560	                let started = false;
561	                let observed = false;
562	                let closed = false;
563	                let receivedReceipt: { totalDollars?: number } | undefined;
564	                let candidateCaptureError: string | undefined;
565	                const finish = async () => {
566	                  closed = true;
567	                  if (!started) await cycles.releaseUndispatchedExploration(savedCycle, operationId, requestHash);
568	                  else if (!observed) {
569	                    await cycles.reconcileExploration(savedCycle, operationId, requestHash, receivedReceipt ?? {});
570	                    observed = true;
571	                  }
572	                };
573	                const observer: ExaUsageObserver = {
574	                  before: async () => {
575	                    const guard = await cycles.explorationDispatchGuard(savedCycle, operationId, requestHash);
576	                    return () => {
577	                      guard();
578	                      if (closed || signal?.aborted) throw new Error("Exploration cancelled before SDK invocation.");
579	                      started = true;
580	                    };
581	                  },
582	                  raw: async (response) => {
583	                    let sourceSnapshot: unknown;
584	                    let snapshotError: string | undefined;
585	                    try {
586	                      sourceSnapshot = structuredClone(response);
587	                    } catch (error) {
588	                      snapshotError = error instanceof Error ? error.message : String(error);
589	                    }
590	                    const costs =
591	                      typeof response === "object" && response !== null && "costDollars" in response
592	                        ? response.costDollars
593	                        : undefined;
594	                    const total =
595	                      typeof costs === "object" && costs !== null && "total" in costs ? costs.total : undefined;
596	                    receivedReceipt = {};
597	                    if (typeof total === "number") {
598	                      try {
599	                        moneyMicros(total);
600	                        receivedReceipt = { totalDollars: total };
601	                      } catch {
602	                        // Malformed totals remain unknown, never genuine reported spend.
603	                      }
604	                    }
605	                    await cycles.reconcileExploration(savedCycle, operationId, requestHash, receivedReceipt);
606	                    observed = true;
607	                    try {
608	                      if (snapshotError !== undefined) throw new Error(snapshotError);
609	                      await capture(sourceSnapshot);
610	                    } catch (error) {
611	                      candidateCaptureError = `Candidate metadata was not confirmed durable; explicitly curate the returned content without repeating paid work. ${error instanceof Error ? error.message : String(error)}`;
612	                    }
613	                  },
614	                };
615	                try {
616	                  const retrieval = retrievalFactory(tool.name, observer);
617	                  if (!retrieval) throw new Error("Retrieval is not enabled; no SDK request was dispatched.");
618	                  const response = await retrieval.execute(id, standalone, signal, onUpdate, ctx);
619	                  await finish();
620	                  const current = await cycles.inspect(savedCycle);
621	                  const accounting = view(current).accounting;
622	                  const candidates =
623	                    current.candidates?.filter((candidate) =>
624	                      candidate.provenance.some((entry) => entry.operationId === operationId),
625	                    ) ?? [];
626	                  return {
627	                    ...response,
628	                    content: [
629	                      ...response.content,
630	                      ...(candidateCaptureError === undefined
631	                        ? []
632	                        : [{ type: "text" as const, text: candidateCaptureError }]),
633	                      {
634	                        type: "text" as const,
635	                        text: `Exa cycle ${savedCycle}; operation ${operationId}.\nPre-call assessment: ${JSON.stringify(assessment)}\nBasis: ${operation.basis}\nLedger overview (not new-call permission): ${JSON.stringify(accounting)}\nCandidate metadata (not automatic evidence selection): ${JSON.stringify(candidates)}\nPublished estimates are not vendor caps; API-reported usage is not verified billing.`,
636	                      },
637	                    ],
638	                    details: {
639	                      ...response.details,
640	                      cycleId: savedCycle,
641	                      operationId,
642	                      requestHash,
643	                      assessment,
644	                      accounting,
645	                      candidates,
646	                      ...(candidateCaptureError === undefined ? {} : { candidateCaptureError }),
647	                    },
648	                  };
649	                } catch (error) {
650	                  try {
651	                    await finish();
652	                  } catch (storageError) {
653	                    return result(
654	                      {
655	                        cycleId: savedCycle,
656	                        operationId,
657	                        requestHash,
658	                        sdkInvoked: started,
659	                        apiReportedReceipt: receivedReceipt,
660	                        receiptDurability: "unconfirmed",
661	                        billingVerified: false,
662	                      },
663	                      `ACCOUNTING_UNAVAILABLE: Usage could not be durably saved. Repair storage, reload and explicitly resume to inspect unknown liabilities. SDK receipt: ${JSON.stringify(receivedReceipt ?? {})}. ${storageError instanceof Error ? storageError.message : String(storageError)}`,
664	                      true,
665	                    );
666	                  }
667	                  throw error;
668	                }
669	              }
670	              if (record) assertArtifactTarget(record, reference);
671	              if (artifactHash !== undefined) throw new Error("Artifact references require active-cycle research.");
672	              const metadata = standalone.metadata;
673	              const attributedCycleId =
674	                typeof metadata === "object" && metadata !== null && "cycleId" in metadata
675	                  ? metadata.cycleId
676	                  : undefined;
677	              if (standalone.previousRunId !== undefined && typeof standalone.previousRunId !== "string")
678	                throw new Error("Invalid previousRunId.");
679	              if (attributedCycleId !== undefined || standalone.previousRunId !== undefined) {
680	                const saved = await cycles.list();
681	                if (saved.some((cycle) => cycle.id === attributedCycleId)) {
682	                  throw new Error("Attributed cycle requests cannot be dispatched as unrelated standalone work.");
683	                }
684	                if (
685	                  saved.some((cycle) =>
686	                    cycle.attempts.some(
687	                      (attempt) =>
688	                        ("runId" in attempt && attempt.runId === standalone.previousRunId) ||
689	                        (Value.Check(agentAttemptSchema, attempt) &&
690	                          attempt.result?.remoteId === standalone.previousRunId),
691	                    ),
692	                  )
693	                ) {
694	                  throw new Error("Recorded cycle attempts cannot be continued as unrelated standalone work.");
695	                }
696	              }
697	              if (!Value.Check(tool.parameters, standalone)) throw new Error("Invalid standalone tool arguments.");
698	              return tool.execute(id, standalone, signal, onUpdate, ctx);
699	            }
700	            if (!record) throw new Error("No active research cycle. Use /exa-research start or resume.");
701	            switch (tool.name) {
702	              case "exa_research_step":
703	                if (!Value.Check(stepParams, params)) throw new Error("Invalid research step arguments.");
704	                {
705	                  const updated = await cycles.recordStep(params);
706	                  return result({ ...updated, cycle: view(updated.cycle) });
707	                }
708	              case "exa_research_summary":
709	                if (!Value.Check(summaryParams, params)) throw new Error("Invalid research summary arguments.");
710	                if (params.mode === undefined || params.mode === "payload" || params.mode === "execution_plan") {
711	                  const artifact = await cycles.preview(params);
712	                  return result({
713	                    artifact,
714	                    requestHash: agentRequestHash(artifact.request),
715	                    previewOnly: true,
716	                  });
717	                }
718	                {
719	                  const current = await cycles.status(params);
720	                  if (!current) throw new Error("No active research cycle. Use /exa-research start or resume.");
721	                  const summary = projectResearchSummary(current, params);
722	                  const summaryView = view(summary.record);
723	                  return result(
724	                    { ...summaryView, selectedEvidence: summary.selectedEvidence },
725	                    `${summary.text}${summaryView.finalReport ? `\nFinal report (recorded gaps and criteria, not automatic verification): ${JSON.stringify(summaryView.finalReport)}` : ""}`,
726	                  );
727	                }
728	              case "exa_research_reset": {
729	                const archived = await cycles.archive();
730	                return result(view(archived), `Archived ${archived.id}.${warning(archived)}`);
731	              }
732	              default:
733	                return tool.execute(id, params, signal, onUpdate, ctx);
734	            }
735	          } catch (error) {
736	            return result(
737	              error instanceof ResearchArtifactError
738	                ? { issues: error.issues }
739	                : error instanceof ExplorationApprovalError
740	                  ? {
741	                      cycleId: error.cycleId,
742	                      tool: error.tool,
743	                      requestHash: error.requestHash,
744	                      request: error.request,
745	                      assessment: error.assessment,
746	                      operatorCommands: [
747	                        `/exa-research approve ${error.cycleId} <total-dollar-ceiling>${error.tool === "web_research_exa" ? " web_research_exa" : ""}`,
748	                        ...(error.assessment.reason === "UNCERTAINTY_APPROVAL_REQUIRED"
749	                          ? [`/exa-research approve-request ${error.cycleId} ${error.requestHash} <assessed-dollars>`]
750	                          : []),
751	                        ...error.assessment.blockedOperationIds
752	                          .filter((operationId) => !error.assessment.conflictingOperationIds.includes(operationId))
753	                          .map(
754	                            (operationId) =>
755	                              `/exa-research approve-liability ${error.cycleId} ${operationId} <assessed-dollars>`,
756	                          ),
757	                      ],
758	                      ...(error.assessment.conflictingOperationIds.length
759	                        ? {
760	                            actionRequired:
761	                              "Investigate conflicting API receipts; uncertainty permission cannot resolve them.",
762	                          }
763	                        : {}),
764	                    }
765	                  : {},
766	              error instanceof Error ? error.message : String(error),
767	              true,
768	            );
769	          }
770	        },
771	      });
772	    },
773	  };
774	}
