} from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

const log = (...a: unknown[]) => console.log(new Date().toISOString().slice(11, 23), ...a);

// ---- controllable mock job -------------------------------------------------
type Job = { id: string; status: "queued" | "running" | "completed"; gets: number };
const jobs = new Map<string, Job>();
let creates = 0;
const mockExa = {
  async create(): Promise<Job> {
    creates++;
    const job: Job = { id: `run_${creates}`, status: "running", gets: 0 };
    jobs.set(job.id, job);
    return job;
  },
  async get(id: string): Promise<Job> {
    const job = jobs.get(id);
    if (!job) throw new Error("404");
    job.gets++;
    return { ...job };
  },
};

// ---- prototype extension ---------------------------------------------------
const observed: string[] = [];
function protoExtension(pi: ExtensionAPI) {
  const timers = new Set<NodeJS.Timeout>();
  const notices = new Map<string, "pending" | "sent" | "acknowledged">();
  pi.on("session_start", (ev, ctx) => {
    observed.push(`session_start:${ev.reason}:hasUI=${ctx.hasUI}:mode=${ctx.mode}:session=${ctx.sessionManager.getSessionId()}`);
  });
  pi.on("session_shutdown", (ev) => {
    observed.push(`session_shutdown:${ev.reason}`);
    for (const t of timers) clearTimeout(t);
    timers.clear();
  });
  pi.on("agent_start", () => observed.push("agent_start"));
  pi.on("agent_settled", (ev, ctx) => {
    observed.push(`agent_settled:aborted=${ev.aborted}`);
    // acknowledgement by observation: look for our custom_message entries
    for (const entry of ctx.sessionManager.getEntries()) {
      if (entry.type === "custom_message" && entry.customType === "exa-proto-completion") {
        const id = (entry.details as { noticeId?: string } | undefined)?.noticeId;
        if (id && notices.get(id) === "sent") {
          notices.set(id, "acknowledged");
          observed.push(`notice_acknowledged:${id}:entry=${entry.id}`);
        }
      }
    }
  });
  pi.registerTool({
    name: "proto_submit",
    label: "Proto submit",
    description: "Submit mocked research after trusted confirmation",
    parameters: Type.Object({ topic: Type.String() }),
    async execute(_id, params, _signal, _onUpdate, ctx) {
      observed.push(`tool:hasUI=${ctx.hasUI}:isIdle=${ctx.isIdle()}`);
      if (!ctx.hasUI) {
        return { content: [{ type: "text", text: "APPROVAL_UNAVAILABLE: no trusted confirmation surface." }], details: { approved: false }, isError: true };
      }
      const approved = await ctx.ui.confirm("Approve Exa research spending?", `Topic: ${params.topic}\nEstimated $0.10`, { timeout: 2_000 });
      observed.push(`confirm:${approved}`);
      if (!approved) return { content: [{ type: "text", text: "Declined; nothing submitted." }], details: { approved }, isError: true };
      const job = await mockExa.create();
      const noticeId = `notice_${job.id}`;
      notices.set(noticeId, "pending");
      const poll = async () => {
