const waitFor = (pred, ms = 8000) => new Promise((res, rej) => { const t = setTimeout(() => rej(new Error("timeout waiting; last events: " + events.slice(-8).map(e=>e.type).join(","))), ms); waiters.push({ pred, res: (e) => { clearTimeout(t); res(e); } }); });
createInterface({ input: child.stdout }).on("line", (line) => {
  let rec; try { rec = JSON.parse(line); } catch { console.log("[raw]", line); return; }
