    console.log("UI REQUEST:", rec.method, rec.title ?? "", (rec.message ?? "").split("\n")[0]);
    if (rec.method === "confirm") send({ type: "extension_ui_response", id: rec.id, confirmed: true });
  }
  if (rec.type === "message_end" && rec.message?.role) console.log("message_end:", rec.message.role, JSON.stringify(rec.message.content).slice(0, 110));
  if (rec.type === "response") console.log("response:", rec.command, rec.success, JSON.stringify(rec.data ?? rec.error).slice(0, 100));
  if (rec.type === "agent_settled") console.log("agent_settled aborted=", rec.aborted);
  for (const w of waiters.splice(0)) { if (w.pred(rec)) w.res(rec); else waiters.push(w); }
});
child.on("exit", (c) => console.log("pi exited", c));
try {
  send({ id: "p1", type: "prompt", message: "research Laya versus Jev" });
  await waitFor((e) => e.type === "agent_settled");
  send({ id: "p2", type: "prompt", message: "unrelated chat" });
  await waitFor((e) => e.type === "agent_settled");
  send({ id: "c1", type: "prompt", message: "/exa-proto complete run_1" });
  await waitFor((e) => e.type === "response" && e.id === "c1");
  await waitFor((e) => e.type === "agent_settled");
  send({ id: "g1", type: "get_entries" });
  const entries = await waitFor((e) => e.type === "response" && e.id === "g1");
  console.log("entry types:", entries.data.entries.map((e) => e.type + (e.customType ? ":" + e.customType : "")).join(" "));
  send({ id: "n1", type: "new_session" });
  await waitFor((e) => e.type === "response" && e.id === "n1");
  send({ id: "s1", type: "prompt", message: "/exa-proto state" });
  const st = await waitFor((e) => e.type === "extension_ui_request" && e.method === "notify" && e.message?.includes("attempts"));
  const state = JSON.parse(st.message);
  console.log("after new_session monitor:", JSON.stringify(state.attempts[0].monitor), "notice:", JSON.stringify(state.attempts[0].notice));
} catch (e) { console.log("ERR", e.message); }
child.stdin.end(); setTimeout(() => child.kill(), 1500);
